def _check_args(width, indent):
    # Rule 6: width is an int >= 1 (bool is rejected even though it subclasses int),
    # and indent must be a string shorter than width.
    if not isinstance(width, int) or isinstance(width, bool) or width < 1:
        raise ValueError("width must be an int >= 1")
    if not isinstance(indent, str):
        raise ValueError("indent must be a str")
    if len(indent) >= width:
        raise ValueError("indent must be shorter than width")


def _wrap_paragraph(words, width, indent):
    """Greedy-fill the words of one paragraph; return the lines, indent included."""
    contents = []  # finished line contents, without indent
    cur = None     # content of the line being filled, or None if it is still empty

    def capacity(line_index):
        # The first line of a paragraph has no indent; later lines do.
        return width if line_index == 0 else width - len(indent)

    for word in words:
        while True:
            cap = capacity(len(contents))
            if cur is None:
                if len(word) <= cap:
                    cur = word
                    break
                # Rule 5: the word does not fit even on an empty line; fill this
                # line with as much of it as fits and continue with the rest.
                contents.append(word[:cap])
                word = word[cap:]
                continue
            if len(cur) + 1 + len(word) <= cap:
                cur = cur + " " + word
                break
            # Rule 3: the word does not fit on the current line; start a new one.
            contents.append(cur)
            cur = None
    if cur is not None:
        contents.append(cur)

    # Rule 4: every line except the paragraph's first starts with the indent.
    return [contents[0]] + [indent + c for c in contents[1:]]


def wrap(text, width, indent=""):
    """Wrap `text` to lines of at most `width` characters. See TASK.md."""
    _check_args(width, indent)
    lines = []
    # Rule 1: each "\n"-separated piece is a paragraph wrapped on its own.
    for paragraph in text.split("\n"):
        # Rule 2: a word is a maximal run of non-whitespace characters.
        words = paragraph.split()
        if not words:
            # A paragraph with no words gives exactly one empty line, no indent.
            lines.append("")
        else:
            lines.extend(_wrap_paragraph(words, width, indent))
    return lines
